INSERT INTO `external_jobs` (`external_job_id`, `title`, `company`, `location`, `description`, `salary`, `date_fetched`, `url`, `source`, `closing_date`) VALUES
(118, 'Senior Software Developer II: Angular & Full-Stack', 'Boardroom Appointments', 'Sandton, ZA', 'A technology firm in Sandton is looking for an experienced Software Developer II to design and develop new applications for their customer base. The ideal candidate will possess a Bachelor\\\'s degree in Computer Science and at least 8 years of software development experience. Strong knowledge of the Angular framework and system architecture is essential. This role involves collaboration with other engineers to meet all development requirements, along with gaining experience in Linux system administration.\\n#J-18808-Ljbffr', '', '2026-01-29 12:02:00', 'https://www.adzuna.co.za/details/5601764998?utm_campaign=google_jobs_apply&utm_source=google_jobs_apply&utm_medium=organic', 'external', NULL),
(119, 'Software Developer (Java, SQL) (CH1182)', 'Capital H Staffing', 'Stellenbosch, ZA', 'Description\\n\\nOur client is a Stellenbosch-based technology company that designs and builds digital solutions across Africa to enable more productive societies.\\n\\nThey are seeking Software Developers with 8+ years’ programming experience (any language, ideally Java) and strong SQL (PostgreSQL) skills.\\n\\nWe’re looking for a team player, problem-solver, and quick learner—dependable, dedicated, impact-driven, and committed to producing high-quality work.\\n\\nQualification and Experience\\n• Tertiary qualifications in information technology will count in an applicant’s favour.\\n• 8+ Years’ of relevant development experience\\n• Strong SQL experience, i.e. strong data processing skills (statistical analysis experience will be beneficial).\\n\\nAdvantageous\\n• Experience in Java\\n• Experience with AI and machine learning frameworks (e.g., TensorFlow, PyTorch).\\n• Familiarity with NLP and chatbot development.\\n• Experience with the WhatsApp Business API and other messaging platforms.\\n\\nWhat to expect\\n• Passionate and dedicated team members - We work hard and support each other because we are passionate about what we do and the impact we are making.\\n• Growth opportunities - We have annual personal development discussions to craft out your journey ahead. We have 5 study leave days for those that are pursuing a qualification or certification.\\n• Flexibility - 3 remote work days with core hours being 10:00 - 15:00. We are output, not input focused.\\n• An energising environment - We celebrate differences and value individuals. We enjoy celebrating successes, having coffee-walks, playing ping-pong and care about each other\\\'s personal lives.\\n• Income protection & death cover - We care about our staff and their family when unexpected events occur.\\n• Employee Wellness Programme - We are holistic beings and therefore we invest in the health and wellbeing of our staff.\\n\\nGeneral\\n• We are committed to fair and inclusive hiring. All suitably qualified applicants are welcome to apply.\\n• Preference may be given in line with our client’s Employment Equity plan and applicable legislation.\\n• Applicants must have the legal right to work in South Africa at the time of application.\\n• Only shortlisted candidates will be contacted. If you do not hear from us within 30 days, please consider your application unsuccessful.\\n• Please include your current remuneration (CTC), salary expectation, and notice period (optional but helpful for screening).\\n• By applying, you consent to the processing of your personal information for recruitment purposes in accordance with POPIA.', '', '2026-01-29 12:02:00', 'https://www.pnet.co.za/jobs--Software-Developer-Java-SQL-CH1182-Stellenbosch-South-Africa-Capital-H-Staffing--4127870-inline.html?utm_campaign=google_jobs_apply&utm_source=google_jobs_apply&utm_medium=organic', 'external', NULL);

